import {Ampe} from './ampe.js';
import {Stay} from './stay.js';
import {Mode,makeStool} from './mode-base.js';
import {THREE,actor,animateActor,box,cylinder,sphere,ball,ring,distance,palette,moveActor} from './world.js';
export function createMotionMode(ctx){const id=ctx.game.id;if(id==='antoakyire')return new CircleChase(ctx);if(id==='ampe')return new Ampe(ctx);if(id==='chaskele')return new Chaskele(ctx);if(id==='stay')return new Stay(ctx);if(['alikoto','kpitinge','alasa'].includes(id))return new Aim(ctx);if(['tumatu','zanzama','numbers'].includes(id))return new Steps(ctx);return new Rhythm(ctx);}
class Chaskele extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera('aim');this.you=this.player(0,4);this.you.rotation.y=Math.PI;this.thrower=this.player(0,-7,0x469d86);this.b=new THREE.Group();this.root.add(this.b);const can=cylinder(.12,.1,.21,0xa7a598,0,0,0,this.b,7);can.rotation.z=.32;can.scale.x=.75;this.tyre=new THREE.Mesh(new THREE.TorusGeometry(.9,.2,8,24),new THREE.MeshStandardMaterial({color:0x292d27}));this.tyre.rotation.x=Math.PI/2;this.tyre.position.set(0,.2,6);this.root.add(this.tyre);this.bat=cylinder(.07,.13,1.8,0x9c6a37,.6,1.1,4,this.root,9);this.swung=0;this.attempt=0;this.conceded=0;this.phase='ready';this.v=new THREE.Vector3();this.setActions([{id:'swing',label:'Swing',key:'Space'}]);this.note('Protect the tyre. Move across, then time the stick through the can. The thrower retrieves it from where you strike it.');}
 serve(){
  this.phase='flight';this.time=0;this.b.position.set(this.thrower.position.x,1.3,this.thrower.position.z+.3);const duration=THREE.MathUtils.clamp(distance(this.thrower,{x:0,z:6})/((9+Math.random()*3)*this.difficultyTuning.speed),.65,1.55),x=(Math.random()-.5)*.7,z=6+(Math.random()-.5)*.3;
  this.v.set((x-this.b.position.x)/duration,(.13-this.b.position.y+4*duration*duration)/duration,(z-this.b.position.z)/duration);this.hitBall=false;this.thrower.userData.pose='keeperThrow';this.thrower.userData.poseUntil=this.age+.45;
 }
 action(){if(this.swung>0||this.phase!=='flight')return;this.swung=.42;this.you.userData.pose='reach';this.ui.sound('swing');}
 endThrow(scored=false){
  this.attempt++;if(scored){this.conceded++;this.note('In the tyre! Line up earlier for the next throw.');this.ui.sound('miss');}
  else if(!this.hitBall)this.note('The can missed the tyre. Get ready for the next throw.');
  if(this.attempt>=10)return this.finish(this.conceded<4?'THE TYRE IS SAFE':'CHASKELE ROUND COMPLETE',`${this.score} struck away · ${this.conceded} in the tyre.`,this.conceded<4);
  this.v.set(0,0,0);this.b.position.set(THREE.MathUtils.clamp(this.b.position.x,-9,9),.11,THREE.MathUtils.clamp(this.b.position.z,-11,8));this.phase='retrieve';this.time=0;
 }
 update(dt){
  const input=this.input.vector(),old=this.you.position.x,target=Math.abs(input.x)>.01?this.you.position.x+input.x*3:this.aimX??this.you.position.x;this.you.position.x=THREE.MathUtils.clamp(this.you.position.x+THREE.MathUtils.clamp(target-this.you.position.x,-dt*5,dt*5),-4,4);this.you.userData.run=Math.abs(this.you.position.x-old)/Math.max(dt*5,.001);
  this.you.userData.pose=this.swung>0?'reach':'idle';this.thrower.userData.pose=this.age<(this.thrower.userData.poseUntil||0)?'keeperThrow':this.phase==='ready'?'keeperHold':'idle';
  this.status(`${this.score} STRUCK AWAY · ${this.conceded} IN TYRE`,`${Math.min(10,this.attempt+1)} / 10 THROWS`);
  const steps=Math.max(1,Math.ceil(dt*120)),step=dt/steps;
  for(let n=0;n<steps;n++){
   this.swung=Math.max(0,this.swung-step);const progress=1-this.swung/.42;this.bat.position.set(this.you.position.x+.25,.8,4);this.bat.rotation.set(.2,-1.2+progress*2.4,this.swung>0?-1.2+Math.sin(progress*Math.PI)*1.9:-.5);
   if(this.phase!=='flight')continue;
   this.b.position.addScaledVector(this.v,step);this.v.y-=8*step;this.b.rotation.x+=this.v.z*step*2;this.b.rotation.z+=step*6;
   if(Math.abs(this.swung-.255)<.105*this.difficultyTuning.window&&!this.hitBall&&Math.abs(this.b.position.z-4)<.6&&Math.abs(this.b.position.x-this.you.position.x)<1&&this.b.position.y<1.9){
    const offset=this.b.position.x-this.you.position.x,quality=1-Math.min(1,Math.abs(progress-.4)*2);this.v.set(offset*9,2.5+quality*2,-9-quality*8);this.hitBall=true;this.score++;this.note('Struck away! The thrower has to retrieve the can.');this.ui.sound('stone');
   }
   const radial=distance(this.b,{x:0,z:6});
   if(this.b.position.y<.34&&radial<.61){this.endThrow(true);break;}
   if(this.b.position.y<.4&&radial>.64&&radial<1.12){const nx=this.b.position.x/radial,nz=(this.b.position.z-6)/radial,speed=this.v.x*nx+this.v.z*nz;if(speed<0){this.v.x-=1.45*speed*nx;this.v.z-=1.45*speed*nz;this.v.y=Math.max(this.v.y,1.2);}}
   if(this.b.position.y<.11){this.b.position.y=.11;this.v.y=Math.abs(this.v.y)>.55?Math.abs(this.v.y)*.28:0;this.v.x*=Math.exp(-step*3);this.v.z*=Math.exp(-step*3);}
   if(this.b.position.z>8||this.b.position.z<-11||Math.abs(this.b.position.x)>9||this.time>4){this.endThrow();break;}
  }
  if(this.phase==='retrieve'){
   this.thrower.userData.run=moveActor(this.thrower,this.b.position,5,dt);
   if(distance(this.thrower,this.b)<.45){this.phase='return';this.returnTo={x:THREE.MathUtils.clamp(this.thrower.position.x,-5,5),z:Math.min(this.thrower.position.z,1)};this.thrower.userData.pose='knees';}
  }else if(this.phase==='return'){
   this.thrower.userData.run=moveActor(this.thrower,this.returnTo,4,dt);this.b.position.set(this.thrower.position.x,1.2,this.thrower.position.z+.2);
   if(distance(this.thrower,this.returnTo)<.1){this.phase='ready';this.time=0;}
  }else if(this.phase==='ready'){this.thrower.userData.run=0;this.b.position.set(this.thrower.position.x,1.2,this.thrower.position.z+.2);if(!this.networked&&this.time>1)this.serve();}
 }
 hit({point}){if(point)this.aimX=THREE.MathUtils.clamp(point.x,-4,4);}
}
class Aim extends Mode{
 constructor(ctx){super(ctx);this.id=ctx.game.id;this.world.setCamera(this.id==='alikoto'?'close':'aim');this.you=this.player(-2,4);this.you.rotation.y=.6;this.attempt=0;this.phase='ready';this.aim=0;this.power=.5;this.good=false;this.v=new THREE.Vector3();this.max=this.id==='alasa'?6:5;this.prop=new THREE.Group();this.root.add(this.prop);if(this.id==='alikoto'){cylinder(.55,.05,.8,0xc44d36,0,.4,0,this.prop,16);cylinder(.55,.55,.07,0xf4cb58,0,.82,0,this.prop);cylinder(.05,.05,.6,0x3e6a59,0,1.12,0,this.prop);this.prop.position.set(0,.05,0);this.circle(0,0,2);this.setActions([{id:'spin',label:'Spin',key:'Space'},{id:'land',label:'Land',key:'E'}]);this.note('Spin the top, then Land when it is upright.');}else if(this.id==='kpitinge'){cylinder(.055,.1,1.3,0xe8c87f,0,0,0,this.prop,8);this.prop.position.set(0,1.1,4);const mound=sphere(1.7,0xcba875,0,.1,-3,this.root);mound.scale.y=.3;this.circle(0,-3,1.3);this.setActions([{id:'throw',label:'Throw peg',key:'Space'}]);this.note('Aim left/right. Throw when the peg points up.');}else{sphere(.16,0x9f4f24,0,0,0,this.prop,10);this.prop.position.set(0,.17,5);cylinder(.42,.42,.025,0x3c2d20,0,.012,-4,this.root);this.circle(0,-4,.65);this.aimLine=box(.035,.02,3,0xf0d090,0,.04,3.5,this.root);this.setActions([{id:'flick',label:'Flick seed',key:'Space'},{id:'power',label:'Power',key:'E'}]);this.note('Aim with left/right. Set power with E, then Flick.');}}
 action(id){if(this.phase==='result'||this.done)return;if(this.id==='alikoto'){if(id==='spin'&&this.phase==='ready'){this.phase='spin';this.time=0;this.note('Wait for it… Land when upright.');this.ui.sound('swing');}else if(id==='land'&&this.phase==='spin'){this.good=Math.abs(this.prop.rotation.z)<.16;this.phase='result';this.time=0;this.prop.rotation.z=this.good?0:Math.PI/2;this.settle(this.good,this.good?'Standing! Beautiful touch.':'It fell on its side.');}}else if(this.id==='kpitinge'&&this.phase==='ready'){this.good=Math.abs(this.prop.rotation.z)<.25&&Math.abs(this.aim)<.23;this.phase='flight';this.time=0;this.v.set(Math.sin(this.aim)*5,5,-7);this.ui.sound('swing');}else if(this.id==='alasa'&&this.phase==='ready'){if(id==='power'){this.power=this.power>=1?.25:this.power+.25;return;}this.phase='flight';this.time=0;this.v.set(Math.sin(this.aim)*this.power*18,0,-Math.cos(this.aim)*this.power*18);this.ui.sound('kick');}}
 settle(ok,text,points=1){if(ok)this.score+=points;this.attempt++;this.note(text);this.ui.sound(ok?'point':'miss');this.phase='result';this.time=0;}
 update(dt,t){this.status(this.id==='alasa'?`${this.score} POINTS`:`${this.score} CLEAN LANDINGS`,`${Math.min(this.max,this.attempt+1)} / ${this.max} · ${this.id==='alasa'?'POWER '+Math.round(this.power*100)+'%':''}`);if(this.phase==='result'){if(this.time>1.4){if(this.attempt>=this.max)return this.finish('ROUND COMPLETE',`${this.score} ${this.id==='alasa'?'points':'clean landings'}.`,this.score>0);this.phase='ready';this.time=0;this.prop.rotation.set(0,0,0);this.prop.position.set(0,this.id==='alasa'?.17:this.id==='alikoto'?.05:1.1,this.id==='alikoto'?0:this.id==='alasa'?5:4);this.note(this.id==='alikoto'?'Spin again.':'Line up your next attempt.');}return;}
 if(this.id==='alikoto'&&this.phase==='spin'){this.prop.rotation.y+=dt*18;this.prop.rotation.z=Math.sin(t*4.5)*.65;if(this.time>8)this.settle(false,'The spin ran out.');}if(this.id!=='alikoto'&&this.phase==='ready'){const v=this.input.vector();this.aim=THREE.MathUtils.clamp(this.aim+v.x*dt*.6,-.55,.55);if(this.id==='kpitinge'){this.prop.rotation.z=Math.sin(t*3.8)*.85;this.prop.rotation.y=this.aim;}else if(this.aimLine){this.aimLine.rotation.y=-this.aim;this.aimLine.position.x=Math.sin(this.aim)*1.5;}}
 if(this.phase==='flight'){this.prop.position.addScaledVector(this.v,dt);if(this.id==='kpitinge'){this.v.y-=9*dt;this.prop.rotation.z+=dt*7;if(this.prop.position.y<.65){this.prop.position.y=.65;this.prop.rotation.z=this.good?0:Math.PI/2;this.settle(this.good,this.good?'Planted upright in the sand!':'Not upright. Try another toss.');}}else{const drag=Math.exp(-1.5*dt);this.v.multiplyScalar(drag);this.prop.rotation.x+=dt*15;if(distance(this.prop,{x:0,z:-4})<.45){this.prop.position.y=-.05;this.settle(true,'In the hole! Ten points.',10);}else if(this.v.length()<.3||this.time>4){const d=distance(this.prop,{x:0,z:-4}),points=Math.max(0,5-Math.round(d));this.settle(points>0,`Stopped ${d.toFixed(1)} steps away. ${points} points.`,points);}}}}
 hit({point}){if(this.id!=='alikoto'&&this.phase==='ready')this.aim=THREE.MathUtils.clamp(Math.atan2(point.x,5-point.z),-.55,.55);}
}
class Steps extends Mode{
 constructor(ctx){super(ctx);this.id=ctx.game.id;this.world.setCamera('chase');this.you=this.player(0,8);this.round=0;this.jump=0;this.said=false;this.tiles=[];if(this.id==='tumatu'){this.positions=[[-1,6],[1,4],[-1,2],[1,0],[-1,-2],[1,-4],[-1,-6],[1,-8]];this.positions.forEach(([x,z],i)=>{const tile=box(1.65,.04,1.65,i===3?0x995a43:0xcfad71,x,.02,z,this.root);tile.userData.pick=i;this.text(String(i+1),x,.16,z,'#fff0c4',.45);this.tiles.push(tile);});this.blocked=3;this.next=0;this.setActions([{id:'jump',label:'Jump',key:'Space'}]);this.note('Hop onto square 1. Skip the red blocked square 4.');}else if(this.id==='zanzama'){this.positions=[[-4,0],[0,0],[4,0]];this.positions.forEach(([x,z])=>makeStool(this.root,x,z));this.next=0;this.marker=this.circle(-4,0,1.1);this.setActions([{id:'say',label:'Zanzama!',key:'E'},{id:'sit',label:'Sit down',key:'Space'}]);this.note('Say Zanzama, then sit on the gold-marked stool.');}else{this.positions=[[-6,0],[-2,0],[2,0],[6,0]];this.options=[[4,7,8,9],[9,12,11,15],[21,25,27,23],[31,32,33,35],[42,43,44,45]];this.correct=[1,2,3,0,1];this.optionGroup=new THREE.Group();this.root.add(this.optionGroup);this.showNumbers();this.setActions([{id:'choose',label:'Choose number',key:'Space'}]);this.note('Stand by a stone showing a prime number, then Choose.');}}
 showNumbers(){this.optionGroup.traverse(o=>{o.geometry?.dispose();o.material?.map?.dispose();o.material?.dispose();});this.optionGroup.clear();this.positions.forEach(([x,z],i)=>{const tile=box(2,.4,1.8,0x88775c,x,.2,z,this.optionGroup);tile.userData.pick=i;const l=this.text(String(this.options[this.round][i]),x,.8,z,'#ffe3a3',.6);this.optionGroup.attach(l);});}
 action(id){if(this.done||this.delay>0)return;if(this.id==='tumatu'&&this.jump<=0){this.jump=.65;this.ui.sound('jump');}else if(this.id==='zanzama'){if(id==='say'){this.said=true;this.note('Zanzama! Now take the highlighted seat.');this.ui.sound('call');}else if(distance(this.you,{x:this.positions[this.next][0],z:0})<1.5*this.difficultyTuning.window){if(this.said){this.score++;this.note('You remembered!');}else this.note('You forgot the word. No point this round.');this.you.userData.pose='knees';this.delay=1;this.round++;}else this.note('Move to the highlighted stool first.');}else if(this.id==='numbers'){const idx=this.positions.findIndex(([x,z])=>distance(this.you,{x,z})<1.5);if(idx<0){this.note('Move close to a numbered stone.');return;}const ok=idx===this.correct[this.round];if(ok)this.score++;this.note(ok?'Correct! That is prime.':'Not prime. The answer was '+this.options[this.round][this.correct[this.round]]+'.');this.ui.sound(ok?'point':'miss');this.round++;this.delay=1;}}
 hit({point}){this.input.target=point;}
 update(dt){this.move(this.you,dt,5.3,9);if(this.delay>0){this.delay-=dt;if(this.delay<=0){if(this.round>=5)return this.finish('ROUND COMPLETE',`${this.score} of 5 correct.`,this.score>=3);if(this.id==='zanzama'){this.next=(this.next+1)%3;this.marker.position.x=this.positions[this.next][0];this.said=false;this.you.userData.pose='idle';this.note('Remember the word before the next seat.');}else if(this.id==='numbers')this.showNumbers();}return;}if(this.id==='tumatu'){if(this.jump>0){this.jump-=dt;this.you.userData.jump=Math.sin(Math.max(0,this.jump)/.65*Math.PI)*1.2;if(this.jump<=0){this.you.userData.jump=0;const q=this.positions[this.next];if(distance(this.you,{x:q[0],z:q[1]})<1.1){this.tiles[this.next].material.color.set(0x57966a);this.score++;this.next++;if(this.next===this.blocked)this.next++;this.ui.sound('point');if(this.next>=8)return this.finish('CLEAN FOOTWORK!','You crossed the hopscotch course.');this.note('Now hop onto square '+(this.next+1)+'.');}else this.note('Land on square '+(this.next+1)+'.');}}this.status(`${this.score} / 7 HOPS`,`NEXT: ${this.next+1}`);}else this.status(`${this.score} POINTS`,`${this.round+1} / 5`);}
}
class Rhythm extends Mode{
 constructor(ctx){super(ctx);this.id=ctx.game.id;this.world.setCamera('close');this.you=this.player(0,0);this.round=0;this.misses=0;this.phase='ready';this.cycle=0;this.lastCycle=0;this.jump=0;this.pose=0;this.targetPose=0;this.passed=false;this.rate=2;this.circle(0,0,3.2);if(this.id==='skipping'){this.left=this.player(-2.5,0,0x389575);this.right=this.player(2.5,0,0xe2b74e);const geom=new THREE.BufferGeometry();geom.setAttribute('position',new THREE.BufferAttribute(new Float32Array(65*3),3));this.rope=new THREE.Line(geom,new THREE.LineBasicMaterial({color:0xe7d6a3,linewidth:3}));this.root.add(this.rope);this.setActions([{id:'jump',label:'Jump!',key:'Space'}]);this.note('Jump as the rope sweeps under your feet.');}else if(this.id==='kyekyekule'){this.you.position.set(-1.6,0,1);this.leader=this.player(1.6,-.5,0x429778);this.poses=['head','hips','knees'];this.setActions([{id:'head',label:'Head',key:'Space'},{id:'hips',label:'Hips',key:'E'},{id:'knees',label:'Knees',key:'Q'}]);this.phase='watch';this.targetPose=Math.floor(Math.random()*3);this.note('Watch the leader, then copy the pose.');}else if(this.id==='chempe'){this.you.position.set(-1.6,0,1);this.neighbour=this.player(1.6,0,0x47987b);this.fruit=sphere(.3,0xe8ac32,1,1,0,this.root);this.called=false;this.shared=false;this.setActions([{id:'call',label:'Chempε!',key:'E'},{id:'accept',label:'Accept',key:'Space'},{id:'share',label:'Share equally',key:'Q'}]);this.note('Call the pact before you accept, then share.');}else{this.ringPlayers=[];for(let i=0;i<6;i++){const angle=i*Math.PI/3;const p=i===0?this.you:this.player(Math.sin(angle)*2.7,Math.cos(angle)*2.7,i%2?0x4e9679:0xc9ad57);p.position.set(Math.sin(angle)*2.7,0,Math.cos(angle)*2.7);p.rotation.y=angle+Math.PI;p.userData.pose='knees';this.ringPlayers.push(p);}this.you.userData.pose='idle';this.marker=sphere(.16,0xffcd52,0,.5,2.7,this.root);this.setActions([{id:'pass',label:this.id==='mbobagor'?'Pass stone':'Withdraw foot',key:'Space'}]);this.note(this.id==='mbobagor'?'Pass when the stone reaches you at the front.':'Withdraw when the golden counter reaches your foot.');this.lastCycle=-1;}}
 action(id){if(this.done||this.delay>0)return;if(this.id==='skipping'){if(this.jump<=0){this.jump=.7;this.ui.sound('jump');}}else if(this.id==='kyekyekule'&&this.phase==='copy'){const ok=id===this.poses[this.targetPose];this.you.userData.pose=id;if(ok)this.score++;this.round++;this.note(ok?'Perfect. Same move!':'Watch closely next time.');this.ui.sound(ok?'point':'miss');this.phase='result';this.time=0;}else if(this.id==='chempe'){if(id==='call'&&this.phase==='ready'){this.called=true;this.note('Pact remembered. Accept, then share.');}else if(id==='accept'&&this.phase==='ready'){this.phase='holding';this.fruit.position.set(-1.3,1.1,1);this.note(this.called?'Now share equally.':'You forgot the call. Share to finish the exchange.');}else if(id==='share'&&this.phase==='holding'){this.fruit.position.set(0,1,.5);this.you.userData.pose=this.neighbour.userData.pose='clap';if(this.called)this.score++;this.round++;this.phase='result';this.time=0;this.note(this.called?'Everyone gets a share.':'Pact missed, but everyone still gets a share.');this.ui.sound('point');}}else if(['pempenaa','mbobagor'].includes(this.id)){const pos=(this.time/this.rate)%6;if(pos<.65||pos>5.65){if(!this.passed){this.score++;this.passed=true;this.marker.material.color.set(0x72c889);this.you.userData.pose=this.id==='mbobagor'?'clap':'left';this.note('On the beat!');this.ui.sound('clap');}}else{this.misses++;this.note('Too soon. Wait until it reaches you.');this.ui.sound('miss');this.delay=.5;}}}
 update(dt,t){if(this.delay>0)this.delay-=dt;this.status(`${this.score} POINTS`,this.id==='skipping'||this.id==='mbobagor'?`${this.misses} / 3 MISSES`:`${Math.min(6,this.round+1)} / ${this.id==='chempe'?5:6}`);if(this.id==='skipping'){this.cycle+=dt*(2.8+this.score*.075)*this.difficultyTuning.speed;const arr=this.rope.geometry.attributes.position.array;for(let i=0;i<65;i++){const a=i/64*Math.PI;arr[i*3]=-2.5+5*i/64;arr[i*3+1]=1.2-Math.sin(a)*1.16*Math.cos(this.cycle);arr[i*3+2]=Math.sin(a)*1.16*Math.sin(this.cycle);}this.rope.geometry.attributes.position.needsUpdate=true;this.left.userData.pose=this.right.userData.pose='point';if(this.jump>0){this.jump=Math.max(0,this.jump-dt);this.you.userData.jump=Math.sin(this.jump/.7*Math.PI)*1.1;}const cycle=Math.floor(this.cycle/(Math.PI*2));if(cycle>this.lastCycle){this.lastCycle=cycle;if((this.you.userData.jump||0)>.3){this.score++;this.note('Clean jump!');this.ui.sound('point');}else{this.misses++;this.note('Caught the rope. Jump as it comes down.');this.ui.sound('miss');}}if(this.score>=10||this.misses>=3)this.finish(this.score>=10?'TEN CLEAN JUMPS':'THE ROPE CAUGHT YOU',`${this.score} clean jumps.`,this.score>=10);}
 else if(this.id==='kyekyekule'){if(this.phase==='watch'){this.leader.userData.pose=this.poses[this.targetPose];if(this.time>1.3){this.phase='copy';this.time=0;this.note('Your turn: copy the leader.');}}else if(this.phase==='copy'&&this.time>4*this.difficultyTuning.window){this.round++;this.phase='result';this.time=0;this.note('Time ran out. Watch the next move.');}else if(this.phase==='result'&&this.time>1){if(this.round>=6)return this.finish('YOU KNOW THE MOVES',`${this.score} of 6 copied.`,this.score>=4);this.phase='watch';this.time=0;this.targetPose=Math.floor(Math.random()*3);this.you.userData.pose='idle';this.note('Watch the leader…');}}
 else if(this.id==='chempe'){if(this.phase==='result'&&this.time>1.2){if(this.round>=5)return this.finish('SHARING COMPLETE',`${this.score} of 5 pacts remembered.`,this.score>=3);this.phase='ready';this.called=false;this.you.userData.pose=this.neighbour.userData.pose='idle';this.fruit.position.set(1,1,0);this.note('Another offer. Remember the pact.');}}
 else{const cycle=Math.floor(this.time/(this.rate*6));if(cycle!==this.lastCycle){if(this.lastCycle>=0&&!this.passed){this.misses++;this.note('The stone collected in front of you.');}this.lastCycle=cycle;this.passed=false;this.you.userData.pose='idle';this.marker.material.color.set(0xffcd52);}const angle=(this.time/this.rate)%6*Math.PI/3;this.marker.position.set(Math.sin(angle)*2.7,.5,Math.cos(angle)*2.7);if(this.id==='pempenaa')this.round=this.score+this.misses;const goal=this.id==='mbobagor'?10:5;if(this.score>=goal||this.misses>=3)this.finish(this.score>=goal?'THE RHYTHM IS YOURS':'KEEP THE CIRCLE GOING',`${this.score} successful ${this.id==='mbobagor'?'passes':'withdrawals'}.`,this.score>=goal);}}
}

class CircleChase extends Mode {
 constructor(ctx){
  super(ctx);this.world.setCamera([0,11,14,0,1,0]);this.circle(0,0,4);this.seated=[];for(let i=0;i<8;i++){const a=i*Math.PI/4,p=this.player(Math.sin(a)*4,Math.cos(a)*4,i===0?this.settings.color:i%2?0xc4a455:0x4d8b71);p.rotation.y=a+Math.PI;p.userData.pose='knees';this.seated.push(p);}
  this.you=this.seated[0];this.runner=this.player(0,-4.8,0x468d7a);this.cloth=box(.55,.04,.45,0xf6dfaa,0,.04,5,this.root);this.round=0;this.role='chaser';this.seatIndex=0;this.beginRound();
 }
 beginRound(){
  this.angle=this.seatIndex*Math.PI/4+.5;this.youAngle=this.seatIndex*Math.PI/4;this.phase='watch';this.stamina=1;this.cloth.visible=true;this.dropAngle=null;this.chaser=null;this.time=0;this.runner.userData.pose='idle';this.runner.userData.run=1;
  this.seated.forEach((p,i)=>{const a=i*Math.PI/4;p.position.set(Math.sin(a)*4,0,Math.cos(a)*4);p.rotation.y=a+Math.PI;p.userData.pose='knees';p.userData.run=0;});
  this.setActions([{id:'chase',label:this.role==='runner'?'Drop cloth':'Pick up / chase',key:'Space'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);
  this.note(this.role==='runner'?'You carry the cloth. Drop it behind a seated player, then reach their empty place before they tag you.':'Stay seated and watch for the cloth. Pick it up, then chase before the runner reaches your place.');
 }
 action(id){
  if(id!=='chase')return;
  if(this.role==='runner'&&this.phase==='watch'){
   const index=((Math.round(this.angle/(Math.PI/4))%8)+8)%8,seatAngle=index*Math.PI/4+Math.round((this.angle-index*Math.PI/4)/(Math.PI*2))*Math.PI*2;
   if(Math.abs(this.angle-seatAngle)>.22)return this.note('Get directly behind a seated player, then drop the cloth.');
   this.dropIndex=index;this.dropAngle=seatAngle;this.chaser=this.seated[index];this.chaserAngle=seatAngle;this.reaction=(.45+Math.random()*.35)*this.difficultyTuning.window;this.phase='dropped';this.time=0;this.cloth.position.set(Math.sin(seatAngle)*4.7,.04,Math.cos(seatAngle)*4.7);this.note('Cloth down. Pace your sprint and get back to the empty seat.');this.ui.sound('stone');
  }else if(this.role==='chaser'&&this.phase==='dropped'){
   this.phase='pickup';this.time=0;this.you.userData.pose='knees';this.ui.sound('stone');this.note('Cloth picked up. Sprint to catch the runner!');
  }else if(this.phase==='watch')this.note('Wait for the cloth behind your place.');
 }
 result(ok){
  if(this.phase==='result')return;if(ok)this.score++;this.round++;this.phase='result';this.time=0;this.cloth.visible=false;
  const was=this.role;
  if(was==='chaser'&&!ok){this.seated[this.seatIndex]=this.runner;this.runner=this.you;this.role='runner';}
  else if(was==='runner'&&ok){this.seated[this.dropIndex]=this.you;this.runner=this.chaser;this.seatIndex=this.dropIndex;this.role='chaser';}
  this.actors.forEach(p=>p.userData.run=0);this.note(was==='chaser'?(ok?'Tagged before the seat! You keep your place.':'The runner took your place. You now carry the cloth.'):(ok?'You reached the empty seat. The chosen player carries the cloth next.':'Tagged! Keep the cloth for the next round.'));this.ui.sound(ok?'point':'miss');
 }
 update(dt){
  this.status(`${this.score} SUCCESSFUL ROUNDS`,`${Math.min(5,this.round+1)} / 5 · ${this.role==='runner'?'CARRY THE CLOTH':'WATCH YOUR PLACE'} · ENERGY ${Math.round(this.stamina*100)}%`);
  if(this.phase==='result'){
   this.seated.forEach((p,i)=>{const a=i*Math.PI/4;p.userData.run=moveActor(p,{x:Math.sin(a)*4,z:Math.cos(a)*4},5,dt);if(!p.userData.run){p.userData.pose='knees';p.rotation.y=a+Math.PI;}});
   if(this.time>1.5){if(this.round>=5)return this.finish('CIRCLE COMPLETE',`${this.score} of 5 chases or escapes successful.`,this.score>=3);if(this.seated.every(p=>!p.userData.run))this.beginRound();}return;
  }
  const activeHuman=this.role==='runner'||this.phase==='chase',sprinting=activeHuman&&this.input.sprint&&this.stamina>.06;
  this.stamina=THREE.MathUtils.clamp(this.stamina+(sprinting?-.32:.23)*dt,0,1);
  const runnerPace=this.role==='runner'?(sprinting?1.65:1.16):(1.07+Math.sin(this.age*1.7)*.055)*this.difficultyTuning.speed;
  this.angle+=dt*runnerPace;this.runner.position.set(Math.sin(this.angle)*4.8,0,Math.cos(this.angle)*4.8);this.runner.rotation.y=this.angle+Math.PI/2;this.runner.userData.run=runnerPace/1.3;
  if(this.phase==='watch'){
   this.cloth.position.set(this.runner.position.x,1,this.runner.position.z);this.runner.userData.pose='point';
   if(this.role==='chaser'&&this.angle>=this.seatIndex*Math.PI/4+Math.PI*2){this.phase='dropped';this.dropAngle=this.seatIndex*Math.PI/4+Math.PI*2;this.youAngle=this.dropAngle;this.time=0;this.cloth.position.set(Math.sin(this.dropAngle)*4.7,.04,Math.cos(this.dropAngle)*4.7);this.note('The cloth is behind you. Pick it up and chase!');this.ui.sound('call');}
   if(this.role==='runner'&&this.time>18){this.result(false);return;}
  }else this.runner.userData.pose='idle';
  if(this.role==='chaser'){
   if(this.phase==='pickup'&&this.time>.18){this.phase='chase';this.you.userData.pose='idle';}
   if(this.phase==='chase'){this.youAngle+=dt*(sprinting?1.75:1.17);this.you.position.set(Math.sin(this.youAngle)*4.8,0,Math.cos(this.youAngle)*4.8);this.you.rotation.y=this.youAngle+Math.PI/2;this.you.userData.run=1;this.cloth.position.set(this.you.position.x,1,this.you.position.z);if(this.youAngle>=this.angle-.14)return this.result(true);}
   if(this.dropAngle!==null&&this.angle>=this.dropAngle+Math.PI*2)this.result(false);
  }else if(this.phase==='dropped'||this.phase==='chase'){
   this.reaction-=dt;if(this.reaction<=0){this.phase='chase';this.chaser.userData.pose='idle';this.chaserAngle+=dt*1.34*this.difficultyTuning.speed;this.chaser.position.set(Math.sin(this.chaserAngle)*4.8,0,Math.cos(this.chaserAngle)*4.8);this.chaser.rotation.y=this.chaserAngle+Math.PI/2;this.chaser.userData.run=1;this.cloth.position.set(this.chaser.position.x,1,this.chaser.position.z);if(this.chaserAngle>=this.angle-.14)return this.result(false);}
   if(this.angle>=this.dropAngle+Math.PI*2)this.result(true);
  }
 }
}
